import pytest
from attr import ib

def test_type_conflict_message():
    try:
        @ib.define
        class MyClass:
            x: int = ib.field(type=str)
    except ValueError as e:
        assert "Type annotation and type argument cannot both be present for 'x'" in str(e)
        return
    pytest.fail("ValueError not raised")

if __name__ == "__main__":
    test_type_conflict_message()

